#include <assert.h>
#include "crc.h"

static void test_known_vector(void) {
    const uint8_t msg[] = "123456789";
    assert(crc16(msg, 9) == 0x29B1);
}

int main(void) {
    test_known_vector();
    return 0;
}

uint16_t crc16(const uint8_t *data, size_t len) {
    uint16_t crc = 0x0000;
    for (size_t i = 0; i < len; i++) {
        crc = crc16_update(crc, data[i]);
    }
    return crc;
}

void uart_init(uart_t *u, int port) {
    u->port = port;
    u->errors = 0;
    ring_init(&u->rx);
}

uint16_t crc16_update(uint16_t crc, uint8_t byte) {
    crc ^= (uint16_t)byte << 8;
    for (int i = 0; i < 8; i++) {
        crc = (crc & 0x8000) ? (uint16_t)((crc << 1) ^ 0x1021) : (uint16_t)(crc << 1);
    }
    return crc;
}

static void test_full_rejects(void) {
    ring_t r;
    ring_init(&r);
    for (int i = 0; i < RING_CAPACITY; i++) assert(ring_push(&r, (uint8_t)i) == 0);
    assert(ring_push(&r, 0) == -1);
    assert(ring_count(&r) == RING_CAPACITY);
}

int uart_send_frame(uart_t *u, const uint8_t *payload, size_t len) {
    uint16_t crc = crc16(payload, len);
    uint8_t tail[2] = {(uint8_t)(crc >> 8), (uint8_t)(crc & 0xFF)};
    if (uart_write(u, payload, len) < 0) {
        return -1;
    }
    return uart_write(u, tail, 2);
}

static void test_push_pop_order(void) {
    ring_t r;
    ring_init(&r);
    ring_push(&r, 1);
    ring_push(&r, 2);
    uint8_t b;
    assert(ring_pop(&r, &b) == 0 && b == 1);
    assert(ring_pop(&r, &b) == 0 && b == 2);
    assert(ring_pop(&r, &b) == -1);
}

int main(void) {
    uart_t u;
    uart_init(&u, 0);
    const uint8_t hello[] = {'h', 'i'};
    uart_send_frame(&u, hello, sizeof hello);
    int n = uart_poll(&u);
    printf("looped %d bytes, errors=%u\n", n, (unsigned)u.errors);
    return 0;
}
